CREATE TABLE customers (id integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY, firstname varchar(30) NOT NULL, lastname varchar(30) NOT NULL, phone varchar(30) NOT NULL, textreminder boolean DEFAULT FALSE); CREATE TABLE schedules (id integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY,name varchar(30) NOT NULL); CREATE TABLE sections (id integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY,name varchar(30) NOT NULL,schedule integer REFERENCES schedules); CREATE TABLE users (id integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY,firstname varchar(30) NOT NULL,lastname varchar(30) NOT NULL,username varchar(50) NOT NULL,password varchar(100) NOT NULL,schedule integer REFERENCES schedules,role varchar(30) NOT NULL,phone varchar(10)); CREATE TABLE appointments (id integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY,customer integer REFERENCES customers,date date NOT NULL,"startTime" time NOT NULL,"endTime" time NOT NULL,description varchar(200) NOT NULL,section integer REFERENCES sections NOT NULL); CREATE TABLE appointmentedits (id integer PRIMARY KEY GENERATED ALWAYS AS IDENTITY,appointment integer REFERENCES appointments,timestamp timestamp with time zone,previnfo varchar(300) NOT NULL,newinfo varchar(300) NOT NULL,owner integer REFERENCES users); INSERT INTO users (firstname, lastname, username, password, role) VALUES ('ADMIN', 'ADMIN', 'admin', 'admin123', 'admin');